use hec_native_ic::{fp::Fp,poly::Poly,jac::Curve,instance::{prime_factors,factor_base}};
#[derive(Debug)]pub struct Witness{pub a:Vec<i64>,pub lambda:u64,pub u:Poly,pub v:Poly}
fn coefficients(c:&Curve,z:u64)->Option<Vec<i64>>{let f=&c.fp;if c.g!=2||c.f!=Poly::from_coeffs(&[c.f.c[0],0,0,0,0,1])||c.f.c[0]==0||(f.p-1)%5!=0||z>=f.p||z==1||f.pow(z,5)!=1{return None}
 let mut squares=vec![false;f.p as usize];let(mut value,mut delta)=(0,1);for _ in 0..=(f.p-1)/2{if squares[value as usize]{return None}squares[value as usize]=true;value=f.add(value,delta);delta=f.add(delta,2);}
 let factors=prime_factors(f.p-1);let gen=(2..f.p).find(|&x|factors.iter().all(|&r|f.pow(x,(f.p-1)/r)!=1))?;let w=f.pow(gen,(f.p-1)/5);let mut powers=[1;5];for i in 1..5{powers[i]=f.mul(powers[i-1],z);}let stride=powers.iter().position(|&x|x==w)?;let(mut t,mut class)=(1,0);let mut a=vec![0i64;5];for _ in 0..f.p-1{let b=f.add(t,c.f.c[0]);let eta=if b==0{0}else if squares[b as usize]{1}else{-1};a[class]-=eta;t=f.mul(t,gen);class=(class+stride)%5;}if t!=1||class!=0{return None}let eta=if squares[c.f.c[0]as usize]{1}else{-1};if a.iter().sum::<i64>()!=eta{return None}Some(a)}
pub fn witness(c:&Curve,z:u64,ell:u64)->Option<Witness>{let a=coefficients(c,z)?;let f=Fp::new(ell);let p=Poly::from_coeffs(&a.iter().map(|&x|f.from_i64(x)).collect::<Vec<_>>());let phi=Poly::from_coeffs(&[1;5]);let b=p.sub(&Poly::one(),&f);let(g,u,v)=Poly::xgcd(&phi,&b,&f);if g.deg()!=1||g.lc()!=1{return None}let lambda=f.neg(g.c[0]);if u.mul(&phi,&f).add(&v.mul(&b,&f),&f)!=Poly::x_minus(lambda,&f){return None}Some(Witness{a,lambda,u,v})}
pub fn verify(c:&Curve,z:u64,ell:u64,lambda:u64)->bool{if lambda>=ell{return false}witness(c,z,ell).is_some_and(|w|w.lambda==lambda)}
pub fn controls(){let mut points=0;let mut orientations=0;for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let z=(2..p).find(|&x|c.fp.pow(x,5)==1).unwrap();let fb=factor_base(&c);let first=witness(&c,z,ell).unwrap();for e in 1..5{let zz=c.fp.pow(z,e);let w=witness(&c,zz,ell).unwrap();let fl=Fp::new(ell);assert_eq!(w.lambda,fl.pow(first.lambda,e));assert!(verify(&c,zz,ell,w.lambda));assert!(!verify(&c,zz,ell,(w.lambda+1)%ell));for &(x,y)in &fb{let d=c.place(x,y);assert_eq!(c.mul(&d,w.lambda),c.place(c.fp.mul(x,zz),y));points+=1;}println!("ACTION\tp={p}\texponent={e}\tz={zz}\tlambda={}\tcoeff={:?}\tU={:?}\tV={:?}",w.lambda,w.a,&w.u.c[..w.u.n],&w.v.c[..w.v.n]);orientations+=1;}}assert_eq!(orientations,12);eprintln!("action_orientations=12 wrong_lambda_rejections=12 native_place_action_controls={points} proof_is_mathematical_not_formally_verified=true");}
